 * @param {string} [timestamp]
 * @returns {void}
 ***/
export function recordHistory(
	task,
	action,
	timestamp = new Date().toISOString(),
) {
	if (!task || !action) return;
	if (!Array.isArray(task.history)) {
		task.history = [];
	}
	const last = task.history[task.history.length - 1];
	if (
		last &&
		last.action === action &&
